#!/usr/bin/env node
/**
 * Concatenates the small per-feature deferred scripts into a single
 * site-bundle.js so HTML pages can pay one request instead of six.
 *
 * The individual source files remain canonical — edit them, then run
 * `npm run build:bundle` to regenerate. Order matters: analytics-bootstrap
 * sets `window.__gematriaGoogleAnalyticsEnabled` and `dataLayer`, and
 * cookie-consent reads them, so analytics must come first.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = process.cwd();
const SOURCES = [
  'analytics-bootstrap.js',
  'preload-stylesheet.js',
  'cookie-consent.js',
  'ui-feedback.js',
  'conversion-tracking.js',
  'glossary-popup.js',
  'nav-scroll.js',
  'public-theme.js',
];
const OUTPUT = 'site-bundle.js';

const parts = [];
parts.push('/* site-bundle.js — generated by scripts/build-site-bundle.mjs.');
parts.push(' * Do NOT edit this file directly. Edit the sources and rerun');
parts.push(' * `npm run build:bundle`. Sources (concatenated in order):');
for (const f of SOURCES) parts.push(` *   - ${f}`);
parts.push(' */');
parts.push('');

for (const file of SOURCES) {
  const body = readFileSync(join(ROOT, file), 'utf8').replace(/\s+$/, '');
  parts.push(`/* === ${file} === */`);
  parts.push(body);
  parts.push('');
}

const output = parts.join('\n') + '\n';

if (process.argv.includes('--check')) {
  const current = readFileSync(join(ROOT, OUTPUT), 'utf8');
  if (current !== output) {
    console.error(
      `${OUTPUT} is out of sync with its sources. Run \`npm run build:bundle\`.`,
    );
    process.exit(1);
  }
  console.log(`${OUTPUT} is up to date.`);
} else {
  writeFileSync(join(ROOT, OUTPUT), output);
  console.log(`Wrote ${OUTPUT} (${output.length} bytes) from ${SOURCES.length} sources.`);
}
